//! M45 Skills S20: concrete transport-neutral, seat-scoped reaction protocol.
//!
//! A candidate crate for integration by Chat 1 / Chat 4. This is genuine Rust
//! implementation (not an interface-only golden), but not an authoritative
//! match executor, TCP listener, HTTP router, or WASM build. Cargo execution
//! and network certification require a Rust toolchain and host integration.
//! All external views are generated by an explicit public allowlist.

use coachlol_core_state::Team;
use std::collections::BTreeMap;
use std::fmt::Write;

const SCHEMA: &str = "coachlol.m45.reaction-seat.v1";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ReactionKind {
    Combat,
    Pickoff,
}
impl ReactionKind {
    fn wire(self) -> &'static str {
        match self {
            Self::Combat => "combat_reaction",
            Self::Pickoff => "pickoff_reaction",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProtocolError {
    InvalidDecision,
    DuplicateDecision,
    ForeignSeat,
    InvalidTarget,
    UnknownDecision,
    DuplicateHistory,
    InvalidHistoryId,
}

/// Trusted server-side identity mapping, derived from current perspective.
/// MUST NOT be implemented using a query parameter, client-provided map,
/// enemy stable ID or a cache of previously visible aliases.
pub trait SeatIdentityView {
    fn visible_attacker_alias<'a>(
        &'a self,
        observer: Team,
        attacker_internal_id: &str,
    ) -> Option<&'a str>;
}

/// A private server-only record. No Serialize / Debug / public field access.
#[derive(Clone)]
struct PrivateReaction {
    decision_id: String,
    defender_id: String,
    defender_seat: Team,
    attacker_internal_id: String,
    kind: ReactionKind,
}

/// Response DTO contains *no* enemy internal ID. Own defender ID is allowed.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PublicReaction {
    pub decision_id: String,
    pub defender_id: String,
    pub kind: ReactionKind,
    pub attacker_alias: Option<String>,
}
impl PublicReaction {
    fn append_json(&self, out: &mut String) {
        out.push_str("{\"decisionId\":");
        json_string(out, &self.decision_id);
        out.push_str(",\"defenderId\":");
        json_string(out, &self.defender_id);
        out.push_str(",\"kind\":");
        json_string(out, self.kind.wire());
        out.push_str(",\"attackerAlias\":");
        match &self.attacker_alias {
            Some(alias) => json_string(out, alias),
            None => out.push_str("null"),
        }
        out.push('}');
    }
}

/// Frozen PUBLIC event recorded at event-time for exactly one recipient seat.
/// Historical views never re-project using current disguises or clone status.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SealedReactionEvent {
    pub event_id: String,
    pub tick: u64,
    pub kind: ReactionKind,
    pub attacker_alias_at_event: Option<String>,
}
impl SealedReactionEvent {
    fn append_json(&self, out: &mut String) {
        out.push_str("{\"eventId\":");
        json_string(out, &self.event_id);
        out.push_str(",\"tick\":");
        write!(out, "{}", self.tick).expect("write string");
        out.push_str(",\"kind\":");
        json_string(out, self.kind.wire());
        out.push_str(",\"attackerAliasAtEvent\":");
        match &self.attacker_alias_at_event {
            Some(alias) => json_string(out, alias),
            None => out.push_str("null"),
        }
        out.push('}');
    }
}

/// Returned only to the trusted match executor, NEVER a public HTTP body.
/// No Debug/Serialize implementation; internal IDs must not be logged.
pub struct AuthorizedResponse {
    pub decision_id: String,
    pub attacker_internal_id: Option<String>,
}

/// A private authoritative-room-side protocol state. Copy in/out with the
/// match snapshot; never serialize this struct to an external seat.
#[derive(Clone, Default)]
pub struct ReactionProtocol {
    reactions: BTreeMap<String, PrivateReaction>,
    history: BTreeMap<(u8, String), SealedReactionEvent>,
}

fn team_key(team: Team) -> u8 {
    match team { Team::Blue => 0, Team::Red => 1 }
}
fn team_wire(team: Team) -> &'static str {
    match team { Team::Blue => "blue", Team::Red => "red" }
}
fn valid_public_id(id: &str, prefix: &str) -> bool {
    let Some(suffix) = id.strip_prefix(prefix) else { return false };
    !suffix.is_empty() && suffix.len() <= 64 &&
        suffix.bytes().all(|b| b.is_ascii_alphanumeric())
}
fn valid_alias(alias: &str) -> bool {
    let Some(suffix) = alias.strip_prefix("appearance_") else { return false };
    !suffix.is_empty() && suffix.len() <= 64 &&
        suffix.bytes().all(|b| b.is_ascii_alphanumeric())
}
fn verified_alias<V: SeatIdentityView>(
    view: &V, seat: Team, internal: &str,
) -> Option<String> {
    view.visible_attacker_alias(seat, internal)
        .filter(|alias| valid_alias(alias))
        .map(str::to_owned)
}
fn json_string(out: &mut String, value: &str) {
    out.push('"');
    for ch in value.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{0000}'..='\u{001f}' => {
                write!(out, "\\u{:04x}", ch as u32).expect("write string");
            }
            _ => out.push(ch),
        }
    }
    out.push('"');
}

impl ReactionProtocol {
    /// Server-only ingestion following the authoritative combat impact.
    /// Does NOT itself cause damage or create a combat window.
    pub fn register_from_server_impact(
        &mut self,
        decision_id: &str,
        defender_id: &str,
        defender_seat: Team,
        attacker_internal_id: &str,
        kind: ReactionKind,
    ) -> Result<(), ProtocolError> {
        if !valid_public_id(decision_id, "react_") ||
           defender_id.is_empty() || attacker_internal_id.is_empty() ||
           defender_id.len() > 128 || attacker_internal_id.len() > 128 ||
           !defender_id.starts_with(match defender_seat {
               Team::Blue => "blue_", Team::Red => "red_",
           }) {
            return Err(ProtocolError::InvalidDecision);
        }
        if self.reactions.contains_key(decision_id) {
            return Err(ProtocolError::DuplicateDecision);
        }
        self.reactions.insert(decision_id.into(), PrivateReaction {
            decision_id: decision_id.into(), defender_id: defender_id.into(),
            defender_seat, attacker_internal_id: attacker_internal_id.into(), kind,
        });
        Ok(())
    }

    pub fn finish_decision(&mut self, decision_id: &str) -> bool {
        self.reactions.remove(decision_id).is_some()
    }

    fn for_seat<V: SeatIdentityView>(&self, seat: Team, view: &V)
        -> Vec<PublicReaction>
    {
        self.reactions.values()
            .filter(|r| r.defender_seat == seat)
            .map(|r| PublicReaction {
                decision_id: r.decision_id.clone(),
                defender_id: r.defender_id.clone(),
                kind: r.kind,
                attacker_alias: verified_alias(view, seat, &r.attacker_internal_id),
            }).collect()
    }

    /// The exact same allowlisted JSON is used by GET /api/session and SSE.
    /// Caller MUST derive seat from the validated room-bound session token.
    pub fn public_json<V: SeatIdentityView>(&self, seat: Team, view: &V) -> String {
        let mut out = String::from("{\"schema\":");
        json_string(&mut out, SCHEMA);
        out.push_str(",\"seat\":");
        json_string(&mut out, team_wire(seat));
        out.push_str(",\"pendingDecisions\":[");
        for (i, decision) in self.for_seat(seat, view).iter().enumerate() {
            if i != 0 { out.push(','); }
            decision.append_json(&mut out);
        }
        out.push_str("],\"history\":[");
        for (i, event) in self.history.iter()
            .filter(|((owner, _), _)| *owner == team_key(seat))
            .map(|(_, value)| value).enumerate()
        {
            if i != 0 { out.push(','); }
            event.append_json(&mut out);
        }
        out.push_str("]}");
        out
    }
    pub fn sse_frame<V: SeatIdentityView>(&self, seat: Team, view: &V) -> String {
        format!("event: public_state\ndata: {}\n\n", self.public_json(seat, view))
    }

    /// Freeze event-time alias; never re-use current view when replaying past
    /// events. Cannot accept caller-supplied private event text or actor IDs.
    pub fn seal_observed_event<V: SeatIdentityView>(
        &mut self,
        seat: Team,
        decision_id: &str,
        event_id: &str,
        tick: u64,
        view: &V,
    ) -> Result<(), ProtocolError> {
        if !valid_public_id(event_id, "evt_") {
            return Err(ProtocolError::InvalidHistoryId);
        }
        let r = self.reactions.get(decision_id).ok_or(ProtocolError::UnknownDecision)?;
        if r.defender_seat != seat { return Err(ProtocolError::ForeignSeat); }
        let key = (team_key(seat), event_id.to_owned());
        if self.history.contains_key(&key) {
            return Err(ProtocolError::DuplicateHistory);
        }
        let record = SealedReactionEvent {
            event_id: event_id.to_owned(), tick, kind: r.kind,
            attacker_alias_at_event: verified_alias(view, seat, &r.attacker_internal_id),
        };
        self.history.insert(key, record);
        Ok(())
    }

    /// A valid alias must match the CURRENT seat view of this exact private
    /// reaction attacker. Hidden defenders can still make defensive responses
    /// with no target. The legacy stable ID is never an accepted alias.
    pub fn authorize_response<V: SeatIdentityView>(
        &self,
        seat: Team,
        decision_id: &str,
        requested_target_alias: Option<&str>,
        view: &V,
    ) -> Result<AuthorizedResponse, ProtocolError> {
        let r = self.reactions.get(decision_id).ok_or(ProtocolError::UnknownDecision)?;
        if r.defender_seat != seat { return Err(ProtocolError::ForeignSeat); }
        let resolved = match requested_target_alias {
            None => None,
            Some(target) => {
                if !valid_alias(target) ||
                    verified_alias(view, seat, &r.attacker_internal_id).as_deref() != Some(target) {
                    return Err(ProtocolError::InvalidTarget);
                }
                Some(r.attacker_internal_id.clone())
            }
        };
        Ok(AuthorizedResponse {
            decision_id: decision_id.to_owned(),
            attacker_internal_id: resolved,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    struct View<'a> { alias: Option<&'a str> }
    impl SeatIdentityView for View<'_> {
        fn visible_attacker_alias<'a>(&'a self, _: Team, _: &str) -> Option<&'a str> {
            self.alias
        }
    }
    fn protocol(defender: Team, enemy: &str) -> ReactionProtocol {
        let mut p = ReactionProtocol::default();
        let own = if defender == Team::Blue { "blue_MID" } else { "red_MID" };
        p.register_from_server_impact("react_1", own, defender, enemy,
                                      ReactionKind::Combat).unwrap();
        p
    }

    #[test]
    fn bilateral_neeko_and_shaco_never_serialize_private_enemy_ids() {
        for defender in [Team::Blue, Team::Red] {
            for (internal, alias) in [("red_TOP", "appearance_1"),
                                      ("red_MID", "appearance_3"),
                                      ("blue_TOP", "appearance_1"),
                                      ("blue_MID", "appearance_3")] {
                if (defender == Team::Blue && internal.starts_with("blue_")) ||
                   (defender == Team::Red && internal.starts_with("red_")) {
                    continue;
                }
                let p = protocol(defender, internal);
                let view = View { alias: Some(alias) };
                let body = p.public_json(defender, &view);
                assert!(body.contains(alias));
                assert!(!body.contains(internal));
                let frame = p.sse_frame(defender, &view);
                assert_eq!(frame, format!("event: public_state\ndata: {}\n\n", body));
                let other = if defender == Team::Blue { Team::Red } else { Team::Blue };
                assert!(!p.public_json(other, &view).contains("react_1"));
                assert!(!p.sse_frame(other, &view).contains(alias));
            }
        }
    }

    #[test]
    fn fog_after_hit_removes_live_alias_without_removing_response_window() {
        let p = protocol(Team::Blue, "red_TOP");
        let json = p.public_json(Team::Blue, &View { alias: None });
        assert!(json.contains("\"attackerAlias\":null"));
        assert!(json.contains("\"decisionId\":\"react_1\""));
        assert!(!json.contains("red_TOP"));
    }

    #[test]
    fn stable_forged_stale_and_foreign_aliases_fail_closed() {
        let p = protocol(Team::Blue, "red_TOP");
        let view = View { alias: Some("appearance_7") };
        for bad in ["red_TOP", "appearance_1", "entity_1",
                    "appearance_2/../../private", "appearance_"] {
            assert!(matches!(p.authorize_response(Team::Blue, "react_1",
                              Some(bad), &view), Err(ProtocolError::InvalidTarget)));
        }
        assert!(matches!(p.authorize_response(Team::Red, "react_1",
                          Some("appearance_7"), &view), Err(ProtocolError::ForeignSeat)));
        assert_eq!(
            p.authorize_response(Team::Blue, "react_1", Some("appearance_7"), &view)
                .unwrap().attacker_internal_id.as_deref(), Some("red_TOP")
        );
        assert!(p.authorize_response(Team::Blue, "react_1", None,
                 &View { alias: None }).unwrap().attacker_internal_id.is_none());
    }

    #[test]
    fn invalid_trusted_view_input_is_not_reflected_to_clients() {
        let p = protocol(Team::Red, "blue_MID");
        for invalid in ["blue_MID", "entity_17", "appearance_", "appearance_1\nsecret"] {
            let json = p.public_json(Team::Red, &View { alias: Some(invalid) });
            assert!(json.contains("\"attackerAlias\":null"));
            assert!(!json.contains(invalid));
        }
    }

    #[test]
    fn event_time_history_survives_fog_alias_changes_and_restore() {
        let mut p = protocol(Team::Blue, "red_TOP");
        p.seal_observed_event(Team::Blue, "react_1", "evt_1", 4,
                              &View { alias: Some("appearance_1") }).unwrap();
        assert_eq!(p.seal_observed_event(Team::Blue, "react_1", "evt_1", 5,
                              &View { alias: Some("appearance_7") }),
                   Err(ProtocolError::DuplicateHistory));
        let snap = p.clone();
        for view in [View { alias: None }, View { alias: Some("appearance_7") }] {
            let json = p.public_json(Team::Blue, &view);
            assert!(json.contains("\"attackerAliasAtEvent\":\"appearance_1\""));
            assert!(!json.contains("red_TOP"));
            assert_eq!(json, snap.public_json(Team::Blue, &view));
        }
        assert!(!p.public_json(Team::Red, &View { alias: None }).contains("evt_1"));
        assert!(p.finish_decision("react_1"));
        assert!(p.public_json(Team::Blue, &View { alias: None }).contains("evt_1"));
    }

    #[test]
    fn escaping_and_replay_projections_remain_single_line() {
        let p = protocol(Team::Blue, "red_TOP");
        let frame = p.sse_frame(Team::Blue, &View { alias: Some("appearance_1") });
        assert_eq!(frame.matches("\ndata: ").count(), 1);
        assert!(!frame.contains("red_TOP"));
        let mut encoded = String::new();
        json_string(&mut encoded, "quoted \" with newline \n and slash \\");
        assert!(encoded.contains("\\\""));
        assert!(encoded.contains("\\n"));
        assert!(encoded.contains("\\\\"));
        assert!(!encoded.contains('\n'));
    }

    #[test]
    fn defender_id_must_belong_to_authenticated_team() {
        let mut p = ReactionProtocol::default();
        assert_eq!(p.register_from_server_impact(
            "react_1", "red_MID", Team::Blue, "red_TOP", ReactionKind::Combat
        ), Err(ProtocolError::InvalidDecision));
        assert_eq!(p.register_from_server_impact(
            "react_1", "blue_TOP", Team::Red, "blue_MID", ReactionKind::Combat
        ), Err(ProtocolError::InvalidDecision));
        assert!(!p.public_json(Team::Blue, &View { alias: None }).contains("react_1"));
    }

    #[test]
    fn private_identifiers_cannot_be_used_as_public_decision_or_event_ids() {
        let mut p = ReactionProtocol::default();
        for invalid in ["red_TOP", "react_red_TOP", "reaction_1",
                        "react_", "react_1/../red_TOP"] {
            assert_eq!(p.register_from_server_impact(
                invalid, "blue_MID", Team::Blue, "red_TOP",
                ReactionKind::Combat), Err(ProtocolError::InvalidDecision));
        }
        p.register_from_server_impact("react_2", "blue_MID",
                                      Team::Blue, "red_TOP", ReactionKind::Combat).unwrap();
        for invalid in ["red_TOP", "evt_red_TOP", "evt_", "evt_1/private"] {
            assert_eq!(p.seal_observed_event(Team::Blue, "react_2",
                invalid, 5, &View { alias: None }),
                Err(ProtocolError::InvalidHistoryId));
        }
    }
}
